contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address operator, address from, uint256 tokenId, bytes calldata data) public payable {
        bytes4 ret;
        bool success;
        try c.onERC721Received(operator, from, tokenId, data) returns (bytes4 r) {
            ret = r;
            success = true;
        } catch {
            success = false;
        }
        assert(!success || ret == bytes4(keccak256("onERC721Received(address,address,uint256,bytes)")));
    }
}

